def rep(text,label,block):
    pat=re.compile(rf"(?ms)^{re.escape(label)}:\n.*?(?=^[A-Za-z_][A-Za-z0-9_]*:|\Z)")
    m=pat.search(text)
    if not m: raise RuntimeError(f"label not found: {label}")
    return text[:m.start()]+block.rstrip()+"\n\n"+text[m.end():]
def run(root,apply):
    changed=[]
    for rel,L in REPLACEMENTS.items():
        p=root/rel; old=p.read_text(encoding='utf-8'); new=old
        for lab,b in L.items(): new=rep(new,lab,b)
        if new!=old:
            changed.append(rel)
            if apply:p.write_text(new,encoding='utf-8')
    p=root/'data/maps/scripts.asm'; old=p.read_text(encoding='utf-8'); new=old
    marker='/*\nSECTION "Map Scripts 20", ROMX'
    if marker in new:new=new.replace(marker,'SECTION "Map Scripts 20", ROMX',1)
    marker21='\n\nSECTION "Map Scripts 21", ROMX'
    if marker21 in new and '/*\nSECTION "Map Scripts 21", ROMX' not in new:
        new=new.replace(marker21,'\n\n/*\nSECTION "Map Scripts 21", ROMX',1)
    if new!=old:
        changed.append('data/maps/scripts.asm')
        if apply:p.write_text(new,encoding='utf-8')
    p=root/'layout.link'; old=p.read_text(encoding='utf-8')
    new=old.replace('; ROMX $55\n; \t"Map Scripts 20"','ROMX $55\n\t"Map Scripts 20"',1)
    if new!=old:
        changed.append('layout.link')
        if apply:p.write_text(new,encoding='utf-8')
    return changed
def main():
    ap=argparse.ArgumentParser(); ap.add_argument('repo',type=Path); ap.add_argument('--apply',action='store_true'); ap.add_argument('--rom',type=Path)
    a=ap.parse_args()
    if a.rom:
        sha=hashlib.sha1(a.rom.read_bytes()).hexdigest()
        if sha!=EXPECTED_ROM_SHA1: raise SystemExit(f'ROM SHA-1 mismatch: {sha}')
        print('ROM SHA-1 OK:',sha)
    c=run(a.repo,a.apply); print(('APPLIED' if a.apply else 'DRY-RUN')+f': {len(c)} files'); [print(' -',x) for x in c]
if __name__=='__main__':main()
